CREATE TABLE IF NOT EXISTS momna.flow_definitions(definition_key TEXT NOT NULL,definition_version INTEGER NOT NULL CHECK(definition_version>0),flow_type TEXT NOT NULL CHECK(flow_type IN('LIFECYCLE_ROUTER','PERIOD_ONBOARDING','CHECKIN','PARTNER_ONBOARDING','PARTNER_CHECKIN','FUTURE')),variant TEXT,period TEXT,substage TEXT,definition_json JSONB NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1 CHECK(schema_version>0),published_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(definition_key,definition_version));
CREATE TABLE IF NOT EXISTS momna.flow_instances(instance_id UUID PRIMARY KEY,definition_key TEXT NOT NULL,definition_version INTEGER NOT NULL,flow_type TEXT NOT NULL,user_id TEXT NOT NULL,variant TEXT,period TEXT,substage TEXT,transition_scope_id TEXT,status TEXT NOT NULL CHECK(status IN('DRAFT','IN_PROGRESS','COMPLETED','CANCELLED')),current_step_id TEXT,row_version BIGINT NOT NULL DEFAULT 0,start_operation_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,FOREIGN KEY(definition_key,definition_version) REFERENCES momna.flow_definitions(definition_key,definition_version),UNIQUE(user_id,definition_key,start_operation_id));
CREATE INDEX IF NOT EXISTS idx_flow_instances_user_status ON momna.flow_instances(user_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS momna.flow_answers(answer_id BIGSERIAL PRIMARY KEY,instance_id UUID NOT NULL REFERENCES momna.flow_instances(instance_id) ON DELETE CASCADE,field_id TEXT NOT NULL REFERENCES momna.canonical_field_definitions(field_id),payload JSONB,answer_status TEXT NOT NULL CHECK(answer_status IN('ANSWERED','SKIPPED','DEACTIVATED')),operation_id TEXT NOT NULL,source_type TEXT NOT NULL DEFAULT 'FLOW',answered_at TIMESTAMPTZ NOT NULL,deactivated_at TIMESTAMPTZ,active BOOLEAN NOT NULL DEFAULT TRUE,CHECK((answer_status='ANSWERED' AND payload IS NOT NULL) OR answer_status<>'ANSWERED'));
CREATE UNIQUE INDEX IF NOT EXISTS uq_flow_active_answer ON momna.flow_answers(instance_id,field_id) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS uq_flow_answer_operation ON momna.flow_answers(instance_id,operation_id,field_id);
CREATE INDEX IF NOT EXISTS idx_flow_answer_history ON momna.flow_answers(instance_id,field_id,answered_at DESC);
CREATE TABLE IF NOT EXISTS momna.flow_operation_results(instance_id UUID NOT NULL REFERENCES momna.flow_instances(instance_id) ON DELETE CASCADE,operation_id TEXT NOT NULL,result_json JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(instance_id,operation_id));
COMMENT ON TABLE momna.flow_instances IS 'Universal Flow Engine instances; backend owns current and next step.';
COMMENT ON TABLE momna.flow_answers IS 'Flow-local canonical field answer history; deactivation preserves audit evidence.';
